hooks.command:
jq -r '.tool_response.filePath // .tool_input.file_path // empty' | { read -r f
  [ -n "$f" ] && [ -f "$f" ] || exit 0
  case "$f" in
    */com/loopers/domain/*|*/com/loopers/infrastructure/*)
      forbidden='application|interfaces'
      title='의존성 역행 (architecture-rules 절대 규칙)'
      msg='domain 과 infrastructure 는 application·interfaces 를 import 할 수 없습니다. 필요한 값은 인자로 받거나 domain 안에 인터페이스를 두고 바깥에서 구현하세요.' ;;
    */com/loopers/interfaces/*)
      forbidden='domain'
      title='레이어 건너뛰기 (architecture-rules 절대 규칙)'
      msg='interfaces 는 domain 을 직접 import 할 수 없습니다. 반드시 application 을 경유하고, enum 은 *UseCaseDto 안의 enum 을 쓰세요.' ;;
    *) exit 0 ;;
  esac

  bad=$(grep -nE "^import com\.loopers\.($forbidden)\." "$f")
  if [ -n "$bad" ]; then
    jq -nc --arg f "$f" --arg b "$bad" --arg m "$msg" --arg t "$title" '{
      decision: "block",
      reason: ($t + "\n" + $f + "\n" + $b + "\n\n" + $m)
    }'
    exit 0
  fi

  case "$f" in */com/loopers/domain/*) ;; *) exit 0 ;; esac
  emb=$(awk '
    /^[[:space:]]*@Embedded[[:space:]]*$/ { blk=1; ln=NR; col=0; ovr=0; next }
    blk {
      t=$0; sub(/^[[:space:]]+/, "", t)
      if (t ~ /^@AttributeOverride/) { ovr=1 } else if (t ~ /^@Column/) { col=1 }
      if (t !~ /^@/) { if (col && !ovr) print ln ": @Embedded " t; blk=0 }
    }' "$f")
  [ -n "$emb" ] || exit 0
  jq -nc --arg f "$f" --arg b "$emb" '{
    decision: "block",
    reason: ("@Embedded 필드에 @Column 만 붙어 있습니다 — JPA 가 통째로 무시합니다\n" + $f + "\n" + $b + "\n\n컬럼명도 제약도 적용되지 않아 컴파일과 테스트는 통과하고 DDL 만 조용히 틀립니다. 실제로 Member.email 이 이 때문에 UNIQUE 가 빠져 같은 이메일로 중복 가입되던 적이 있습니다.\n@AttributeOverride(name = \"<VO 안의 필드명>\", column = @Column(...)) 로 감싸세요.")
  }'
}
